const raw = $json || {};
const body = raw.body || {};
const headers = raw.headers || {};
// The n8n-openai-bridge (LibreChat's real custom-endpoint chat pipeline) sends
// the shared webhook secret as `Authorization: Bearer <token>`, not the
// `x-govchat-token` header used by direct/manual webhook calls. Accept either.
const directToken = String(headers['x-govchat-token'] || headers['X-Govchat-Token'] || '').trim();
const authHeader = String(headers['authorization'] || headers['Authorization'] || '').trim();
const bearerToken = /^Bearer\s/i.test(authHeader) ? authHeader.slice(authHeader.indexOf(' ') + 1).trim() : '';
const callerToken = directToken || bearerToken;

const stepId = String(body.step_id || '').trim();
const routeMap = {
  'stap1': 'beleidskompas-step-stap1',
  'stap2': 'beleidskompas-step-stap2',
  'stap3': 'beleidskompas-step-stap3',
  'stap4': 'beleidskompas-step-stap4'
};
const path = routeMap[stepId] || routeMap.stap1;
// Forward the CALLER's own token, not the internal env token: each step
// workflow validates it against BELEIDSKOMPAS_N8N_WEBHOOK_TOKEN/N8N_WEBHOOK_TOKEN
// itself and returns a clear ok:false (never throws) on mismatch, so an
// unauthenticated caller cannot get a real answer just by reaching this router.
return [{ json: { route_path: path, payload: body, caller_token: callerToken } }];
